SELECT DISTINCT 
FROM connection c
LEFT JOIN procurement_requirement r ON c.requirement_id = r.id AND r.is_deleted = 0
LEFT JOIN enterprise_profile ep_b ON c.buyer_tenant_id = ep_b.tenant_id AND ep_b.is_deleted = 0
LEFT JOIN enterprise_profile ep_s ON c.supplier_tenant_id = ep_s.tenant_id AND ep_s.is_deleted = 0
WHERE c.is_deleted = 0
  AND (c.buyer_tenant_id = #{tenantId} OR c.supplier_tenant_id = #{tenantId})

    AND c.status = #{status}


    AND c.buyer_tenant_id = #{tenantId}


    AND c.supplier_tenant_id = #{tenantId}


    AND (r.title LIKE CONCAT('%', #{keyword}, '%')
         OR ep_b.company_name LIKE CONCAT('%', #{keyword}, '%')
         OR ep_s.company_name LIKE CONCAT('%', #{keyword}, '%'))


    AND c.requirement_id = #{requirementId}

ORDER BY c.create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT c.id) FROM connection c LEFT JOIN procurement_requirement r ON c.requirement_id = r.id AND r.is_deleted = 0 LEFT JOIN enterprise_profile ep_b ON c.buyer_tenant_id = ep_b.tenant_id AND ep_b.is_deleted = 0 LEFT JOIN enterprise_profile ep_s ON c.supplier_tenant_id = ep_s.tenant_id AND ep_s.is_deleted = 0 WHERE c.is_deleted = 0 AND (c.buyer_tenant_id = #{tenantId} OR c.supplier_tenant_id = #{tenantId})
AND c.status = #{status}
AND c.buyer_tenant_id = #{tenantId}
AND c.supplier_tenant_id = #{tenantId}
AND (r.title LIKE CONCAT('%', #{keyword}, '%') OR ep_b.company_name LIKE CONCAT('%', #{keyword}, '%') OR ep_s.company_name LIKE CONCAT('%', #{keyword}, '%'))
AND c.requirement_id = #{requirementId}

